'use client'

import { useActionState } from 'react-dom'

export default function ContactForm() {
  async function submitContact(prevState: { error?: string; success?: boolean }, formData: FormData) {
    'use server'

    const name = formData.get('name') as string
    const email = formData.get('email') as string
    const message = formData.get('message') as string

    if (!name || !email || !message) {
      return { error: 'All fields are required' }
    }

    console.log('Contact message:', { name, email, message })
    return { success: true }
  }

  const [state, submitAction] = useActionState(submitContact, null)

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={submitAction}>
        <input name="name" placeholder="Name" required />
        <input name="email" type="email" placeholder="Email" required />
        <textarea name="message" placeholder="Message" required />
        <button type="submit">Send Message</button>
      </form>
      {state?.error && <p style={{ color: 'red' }}>{state.error}</p>}
      {state?.success && <p style={{ color: 'green' }}>Message sent successfully!</p>}
    </div>
  )
}

